import{_ as a,o as t,c as n,a3 as r}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"ADR 001 · Serving boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/001-serving-boundaries.md","filePath":"decisions/001-serving-boundaries.md","lastUpdated":1794433168000}'),i={name:"decisions/001-serving-boundaries.md"};function o(s,e,d,c,l,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-001-·-serving-boundaries" tabindex="-1">ADR 001 · Serving boundaries <a class="header-anchor" href="#adr-001-·-serving-boundaries" aria-label="Permalink to &quot;ADR 001 · Serving boundaries&quot;">​</a></h1><p><strong>Status:</strong> Proposed baseline. <strong>Date:</strong> November 5, 2026.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The primary interaction is streaming text chat. Developer familiarity is not a selection criterion. Retrieval and inference latency, browser responsiveness, cancellation, and recovery must be measured together.</p><h2 id="proposed-decision" tabindex="-1">Proposed decision <a class="header-anchor" href="#proposed-decision" aria-label="Permalink to &quot;Proposed decision&quot;">​</a></h2><p>Use Svelte 5, SvelteKit, and TypeScript for the product interface. Use Rust with Axum/Tokio for the live chat service. Let SvelteKit render initial routes and bounded snapshots where useful, then deliver active answer events directly from Rust over SSE. HTTP commands create and cancel runs.</p><p>Keep run policies and evidence handling in application/domain modules with focused ports. Axum, model protocols, NATS, and SQLite are adapters. This is a dependency rule, not a mandate for multiple services or one abstraction per function.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>React with Vite or Next.js remains viable. Go or a carefully isolated FastAPI backend may perform similarly when external model work dominates. Svelte&#39;s reactive model and Rust&#39;s resource control motivate the starting choice; no comparative application benchmark has established a winner.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The UI needs an explicit event client, snapshot cursor, state reducer, replay/gap policy, and cancellation protocol. Initial rendering and active token delivery are separate paths. Retained output fanout is added when independent generation or multiple-viewer requirements justify it.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Compare first visible grounded text, input responsiveness, chunk gaps, memory, long tasks, and cancellation under realistic histories. Test slow devices and concurrent streams. Confirm one terminal state and safe replay under reconnects. See <a href="/knowledge-lab/architecture/frontend">frontend</a>, <a href="/knowledge-lab/architecture/backend">backend</a>, and <a href="/knowledge-lab/architecture/contracts">contracts</a>.</p>',13)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
